const fs = require('fs');

const BASE = 'http://127.0.0.1:9222';
const APP = 'http://127.0.0.1:8000';
const OUT = 'D:/smashbook/screenshots';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const target = await (await fetch(`${BASE}/json/new?about:blank`, { method: 'PUT' })).json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let seq = 0;
  const pending = new Map();

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  };

  await new Promise((resolve) => (ws.onopen = resolve));

  const send = (method, params = {}) =>
    new Promise((resolve) => {
      const id = ++seq;
      pending.set(id, resolve);
      ws.send(JSON.stringify({ id, method, params }));
    });

  const evaluate = async (expression) => {
    const result = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (result.result?.exceptionDetails) {
      throw new Error(JSON.stringify(result.result.exceptionDetails));
    }
    return result.result?.result?.value;
  };

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1200, deviceScaleFactor: 1, mobile: false });

  const nav = async (url) => {
    await send('Page.navigate', { url });
    await sleep(2200);
  };

  const shot = async (name) => {
    const metrics = await send('Page.getLayoutMetrics');
    const height = Math.min(Math.ceil(metrics.result.cssContentSize.height || 1200), 5000);
    const result = await send('Page.captureScreenshot', {
      format: 'png',
      captureBeyondViewport: true,
      clip: { x: 0, y: 0, width: 1440, height, scale: 1 },
    });
    fs.writeFileSync(`${OUT}/app-${name}.png`, Buffer.from(result.result.data, 'base64'));
    console.log(`${name}: ${height}px`);
  };

  await nav(`${APP}/login`);
  await evaluate(`
    document.querySelector('input[name="email"]').value = 'owner@smasharena.id';
    document.querySelector('input[name="password"]').value = 'smashbook123';
    document.querySelector('form').submit();
    'submitted';
  `);
  await sleep(3500);

  const pages = [
    ['dashboard', '/dashboard'],
    ['bookings', '/bookings'],
    ['pos', '/pos'],
    ['cash', '/cash'],
    ['inventory', '/inventory'],
    ['purchase-orders', '/purchase-orders'],
    ['reports', '/reports'],
    ['members', '/members'],
    ['courts', '/courts'],
  ];

  for (const [name, path] of pages) {
    await nav(APP + path);
    await shot(name);
  }

  ws.close();
})().catch((error) => {
  console.error(error);
  process.exit(1);
});

